import itertools

TARGET = 2007
N_MAX = 15

results = {}

for n in range(1, N_MAX + 1):
    found_for_n = False
    successful_colorings = []

    # Iterate through all 2^n colorings.
    # A coloring is represented by a tuple of length n, where 0=Red, 1=Blue.
    for coloring_tuple in itertools.product([0, 1], repeat=n):
        coloring = list(coloring_tuple)

        # Check the condition
        nrrr_count = 0
        bbb_count = 0

        # Iterate over all triples (x, y, z) in {0, 1, ..., n-1}
        for x in range(n):
            for y in range(n):
                for z in range(n):
                    # Check condition (i): same color

                    # Check RRR
                    if coloring[x] == 0 and coloring[y] == 0 and coloring[z] == 0:
                        # Check condition (ii): x+y+z is divisible by n
                        if (x + y + z) % n == 0:
                            nrrr_count += 1

                    # Check BBB
                    elif coloring[x] == 1 and coloring[y] == 1 and coloring[z] == 1:
                        # Check condition (ii): x+y+z is divisible by n
                        if (x + y + z) % n == 0:
                            bbb_count += 1

        total_monochromatic = nrrr_count + bbb_count

        if total_monochromatic == TARGET:
            found_for_n = True
            # Store the coloring found (represented by the tuple)
            successful_colorings.append(coloring_tuple)

    if found_for_n:
        results[n] = successful_colorings

# Output the results in a structured way
print(f"Search complete up to N={N_MAX}")
for n, colorings in results.items():
    print(f"--- N = {n} ---")
    print(f"Found {len(colorings)} successful coloring(s).")
    # Print the first successful coloring found for brevity
    if colorings:
        print(f"Example coloring (0=R, 1=B): {colorings[0]}")

print("\nSummary of successful N values:", list(results.keys()))

